update plm_eco_target t
   set base_row_ver = coalesce((select b.row_ver from mst_bom b where b.bom_id = t.bom_id),
                               (select r.row_ver from mst_routing r where r.routing_id = t.routing_id),
                               (select d.row_ver from mst_doc_rev d where d.doc_rev_id = t.doc_rev_id)),
       row_ver = t.row_ver + 1, updated_at = now(), updated_by = #{by}
 where t.eco_id = #{ecoId}

update plm_eco set status = 'RELEASED', released_at = now(), released_by = #{by},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where eco_id = #{ecoId} and row_ver = #{rowVer} and status = 'APPROVED'

update plm_eco set status = 'CANCELLED', cancel_reason = #{reason},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where eco_id = #{ecoId} and row_ver = #{rowVer} and status in ('DRAFT', 'APPROVED')

update plm_eco_target set seq = #{seq}, change_desc = #{changeDesc}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where target_id = #{targetId}
   and (seq <> #{seq} or change_desc is distinct from #{changeDesc,jdbcType=VARCHAR})
